visual.raw:
const rows = (ctx.data && ctx.data.objects) || [];
const counter = {};
const order = [];
rows.forEach(function (r) {
  const raw = r['textbook.name'];
  const name = (raw === null || raw === undefined || raw === '') ? '未关联教材' : String(raw);
  if (!(name in counter)) { counter[name] = 0; order.push(name); }
  const v = r['reqQty'] != null ? Number(r['reqQty']) : Number(r['quantity'] || 0);
  counter[name] += isNaN(v) ? 0 : v;
});
order.sort(function (a, b) { return counter[b] - counter[a]; });
return {
  tooltip: { trigger: 'axis' },
  legend: { bottom: 0 },
  grid: { left: 16, right: 16, top: 32, bottom: 48, containLabel: true },
  xAxis: { type: 'category', data: order, axisLabel: { rotate: 20, interval: 0 } },
  yAxis: { type: 'value' },
  series: [
    {
      type: 'bar',
      name: '领用数量',
      data: order.map(function (n) { return counter[n]; }),
      barMaxWidth: 40,
      label: { show: true, position: 'top' }
    }
  ]
};
